def largest_prime_factor(n: int):
    largest = -1
    # Divide by 2 to make n odd
    while n % 2 == 0:
        largest = 2
        n //= 2
    # n must be odd at this point
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            largest = i
            n //= i
    # If n is a prime number greater than 2
    if n > 2:
        largest = n
    return largest
</code>

