def is_simple_power(x, n):
    if n == 0:
        return x == 1
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1

    # For negative bases, we need to handle even/odd powers
    if n < 0:
        # If n is negative, n**k is positive if k is even, negative if k is odd
        # We need to find if there exists an integer k such that n**k == x
        abs_n = abs(n)
        if x > 0:
            # We need even k
            k = 0
            val = 1
            while val < x:
                k += 1
                val *= abs_n
                if val > x:
                    break
            if val == x and k % 2 == 0:
                return True
            return False
        else:
            # We need odd k
            k = 0
            val = 1
            while val < abs(x):
                k += 1
                val *= abs_n
                if val > abs(x):
                    break
            if val == abs(x) and k % 2 == 1:
                return True
            return False

    # For positive n > 1
    if x < 1:
        return False

    k = 0
    val = 1
    while val < x:
        k += 1
        val *= n
        if val > x:
            break

    return val == x

