raw_completion:
def count_up_to(n):
    if n <= 2:
        return []

    # Sieve of Eratosthenes to find all primes less than n
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False

    primes = [i for i, prime in enumerate(is_prime) if prime]
    return primes
